oxy_webhelp_navlinks = {"personal_access_tokens-d39307e12768":{"topics":[{"title":"Creating a personal access token","shortdesc":"<p class=\"shortdesc\">Create a personal access token to authenticate to the <span class=\"ph\">RSC<\/span> API under         your own user identity.<\/p>","href":"saas\/creating_personal_access_token.html","attributes":{"data-id":"creating_personal_access_token"},"menu":{"hasChildren":false},"tocID":"creating_personal_access_token-d39307e12788","topics":[]},{"title":"Rotating the personal access token secret","shortdesc":"<p class=\"shortdesc\">Generate a new secret for your personal access token if the current secret is lost or         compromised. Rotating the secret invalidates the existing secret.<\/p>","href":"saas\/rotating_personal_access_token_secret.html","attributes":{"data-id":"rotating_personal_access_token_secret"},"menu":{"hasChildren":false},"tocID":"rotating_personal_access_token_secret-d39307e12802","topics":[]},{"title":"Deleting a personal access token","shortdesc":"<p class=\"shortdesc\">Delete your personal access token to permanently revoke API access using those         credentials.<\/p>","href":"saas\/deleting_personal_access_token.html","attributes":{"data-id":"deleting_personal_access_token"},"menu":{"hasChildren":false},"tocID":"deleting_personal_access_token-d39307e12813","topics":[]},{"title":"Deactivating personal access tokens","shortdesc":"<p class=\"shortdesc\">Deactivate the personal access tokens of one or more users to prevent further API         access with those credentials.<\/p>","href":"saas\/deactivating_personal_access_token.html","attributes":{"data-id":"deactivating_personal_access_token"},"menu":{"hasChildren":false},"tocID":"deactivating_personal_access_token-d39307e12824","topics":[]},{"title":"Managing the personal access token policy","shortdesc":"<p class=\"shortdesc\">Configure organization-wide policy settings for personal access tokens, including         concurrent session limits, inactivity timeout, and session timeout.<\/p>","href":"saas\/managing_pat_policy.html","attributes":{"data-id":"managing_pat_policy"},"menu":{"hasChildren":false},"tocID":"managing_pat_policy-d39307e12835","topics":[]}]}};